 "content": "def transform(grid):
    """Restore zeroed cells in a row-wise periodic colour pattern."""
    h, w = len(grid), len(grid[0])
    # Find the shortest repeating horizontal period that explains the visible
    # patterned cells. Each row may have a different phase, but shares period.
    candidates = []
    for p in range(2, min(12, w) + 1):
        total = matched = 0
        for row in grid:
            buckets = [[] for _ in range(p)]
            for c, v in enumerate(row):
                if v != 0:
                    buckets[c % p].append(v)
            for vals in buckets:
                if vals:
                    total += len(vals)
                    counts = {x: vals.count(x) for x in set(vals)}
                    matched += max(counts.values())
        candidates.append((matched / total if total else 0, p, matched, total))
    best_score = max(x[0] for x in candidates)
    # Prefer the shortest period among essentially equally good fits.
    p = min(x[1] for x in candidates if x[0] >= best_score - 0.015)
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        buckets = [[] for _ in range(p)]
        for c, v in enumerate(row):
            if v != 0:
                buckets[c % p].append(v)
        pattern = []
        for vals in buckets:
            if not vals:
                pattern.append(None)
            else:
                counts = {x: vals.count(x) for x in set(vals)}
                pattern.append(max(counts, key=lambda x: (counts[x], -x)))
        # Fill holes only when the inferred residue has visible evidence.
        for c, v in enumerate(row):
            if v == 0 and pattern[c % p] is not None:
                out[r][c] = pattern[c % p]
    return out
