    # Infer the period from visible interior cells, allowing each row its own
    # phase (the masks may hide arbitrary rectangular patches).
    interior_start = 3
    candidates = []
    for p in range(2, min(12, w - interior_start) + 1):
        score = 0
        for r in range(3, h):
            buckets = [[] for _ in range(p)]
            for c in range(interior_start, w):
                v = grid[r][c]
                if v != 0:
                    buckets[c % p].append(v)
            score += sum(max((vals.count(x) for x in set(vals)), default=0)
                         for vals in buckets)
        candidates.append((score, p))
    best = max(score for score, _ in candidates)
    # Avoid selecting a multiple of the true period when its score ties.
    p = min(p for score, p in candidates if score == best)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                # For each row, use the majority known color in this period
                # residue. This restores masked pixels without changing clues.
                vals = [grid[r][x] for x in range(interior_start, w)
                        if x % p == c % p and grid[r][x] != 0]
                if vals:
                    out[r][c] = max(set(vals), key=lambda x: (vals.count(x), -x))
